    {
        private bool hooked;

        public bool Hooked
        {
            get => hooked;
            set { hooked = value; if (hooked) OnKeyDown += new KeyEventHandler(OnKeyDown); }
        }

        private void OnKeyDown(object sender, KeyEventArgs e)
        {
