    # Start recording
    with hhook:
        while True:
            key = hhook.GetKeyState(0x1)
            if key:
                print("Key pressed: ", key)

            key_up = hhook.GetKeyState(0x2)
            if key_up:
                print("Key released: ", key_up)

if __name__ == "__main__":
    main()
